insert into public.products
  (name, slug, short_description, description, category_id, brand_id, sku, unit_label,
   price, compare_at_price, stock_quantity, sold_count, is_featured, is_flash_sale,
   flash_sale_price, flash_sale_ends_at, is_organic, ingredients, tags, image_url, specifications)
select
  v.name, v.slug, v.short, v.long,
  (select id from public.categories where slug = v.cat),
  (select id from public.brands where slug = v.brand),
  v.sku, v.unit,
  v.price, v.compare, v.stock, v.sold,
  v.flags like '%featured%',
  v.flags like '%flash%',
  case when v.flags like '%flash%' then round(v.price * 0.85, 2) else null end,
  case when v.flags like '%flash%' then now() + interval '3 days' else null end,
  v.flags like '%organic%',
  v.ing, string_to_array(v.tags, ','), v.img,
  jsonb_build_object('Origin', 'Qatar', 'Storage', 'Cool, dry place away from direct sunlight',
    'Pack size', v.unit, 'Shelf life', '9 months from packing')
from (values
('Sidr Honey 500 g', 'sidr-honey-500g', 'Raw sidr honey from highland beekeepers.', 'Cold-extracted sidr honey with a deep amber colour and a warm, herbal finish. Unfiltered and never heated above hive temperature, so the natural pollen and enzymes stay intact.', 'honey', 'golden-hive', 'AB-1000', '500 g', 89, 110, 42, 260, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Sidr_Tree_and_me_connected_with_eachother_through_the_early_morning_sun.jpg/960px-Sidr_Tree_and_me_connected_with_eachother_through_the_early_morning_sun.jpg', '100% pure sidr honey', 'featured,flash', 'honey,raw,premium'),
('Manuka Honey 250 g', 'manuka-honey-250g', 'Certified manuka, thick and aromatic.', 'A premium manuka honey with a smooth, creamy texture and a long, slightly savoury finish. Jarred and tested in small batches for consistency.', 'honey', 'golden-hive', 'AB-1001', '250 g', 165, 195, 18, 96, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Manuka_honey_in_a_bowl.jpg/960px-Manuka_honey_in_a_bowl.jpg', '100% pure manuka honey', 'featured', 'honey,manuka,premium'),
('Wildflower Honey 1 kg', 'wildflower-honey-1kg', 'Everyday honey with a light floral taste.', 'A soft, quickly setting honey gathered from mixed wildflowers. Great for tea, baking and everyday cooking.', 'honey', 'golden-hive', 'AB-1002', '1 kg', 74, 92, 60, 410, 'https://upload.wikimedia.org/wikipedia/commons/6/68/Cornmeal_Fritters_and_Wildflower_Honey_%2816053763002%29.jpg', '100% pure wildflower honey', 'flash', 'honey,everyday'),
('Extra Virgin Olive Oil 1 L', 'extra-virgin-olive-oil-1l', 'First cold press, low acidity.', 'Pressed within hours of harvest from mature olives. Grassy and peppery with a clean finish, made for dipping, salads and low-heat cooking.', 'oil-and-ghee', 'green-valley', 'AB-1003', '1 L', 62, 78, 55, 320, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Bottle_of_olive_oil.jpg/960px-Bottle_of_olive_oil.jpg', '100% extra virgin olive oil', 'featured,flash', 'oil,olive,healthy'),
('Cold Pressed Mustard Oil 1 L', 'mustard-oil-1l', 'Kachi ghani, strong and pungent.', 'Traditional wood-pressed mustard oil with a sharp aroma, the one that makes pickles and fish curries taste like home.', 'oil-and-ghee', 'dildar', 'AB-1004', '1 L', 34, 42, 70, 240, 'https://upload.wikimedia.org/wikipedia/commons/e/e1/Dune_Aura_Mustard_oil_bottle_picture.jpg', '100% cold pressed mustard oil', '', 'oil,mustard,cooking'),
('Virgin Coconut Oil 500 ml', 'coconut-oil-500ml', 'Unrefined, no deodorising.', 'Cold pressed from fresh coconut milk and left unrefined, so the natural coconut aroma stays. Solid below 24 C, liquid above it.', 'oil-and-ghee', 'green-valley', 'AB-1005', '500 ml', 41, 52, 48, 190, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Loaded_Container.jpg/960px-Loaded_Container.jpg', '100% virgin coconut oil', 'organic', 'oil,coconut,organic'),
('Pure Cow Ghee 500 g', 'pure-ghee-500g', 'Slow-simmered from cultured butter.', 'Made by simmering cultured cream butter until the milk solids turn golden, then strained through muslin. Grainy, nutty and rich.', 'oil-and-ghee', 'dildar', 'AB-1006', '500 g', 68, 84, 36, 275, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Butterschmalz-3.jpg/960px-Butterschmalz-3.jpg', 'Cow milk butter, natural culturing culture', 'featured', 'ghee,dairy'),
('Toasted Sesame Oil 250 ml', 'sesame-oil-250ml', 'Roasted, for finishing dishes.', 'Sesame seeds roasted before pressing, giving a dark, fragrant oil meant for finishing noodles, dressings and stir-fries.', 'oil-and-ghee', 'noor-pantry', 'AB-1007', '250 ml', 27, 33, 44, 120, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Nisshin_OilliO_blend_oil.jpg/960px-Nisshin_OilliO_blend_oil.jpg', '100% toasted sesame oil', '', 'oil,sesame,asian'),
('Ajwa Dates 500 g', 'ajwa-dates-500g', 'Soft, dark and caramel-sweet.', 'Hand-picked ajwa dates with a soft, moist flesh and a fine crust. Packed in a resealable jar to keep them supple.', 'dates', 'desert-gold', 'AB-1008', '500 g', 55, 69, 30, 310, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Ajwa_dates.JPG/960px-Ajwa_dates.JPG', '100% natural ajwa dates', 'featured,flash', 'dates,premium,gift'),
('Medjool Dates 1 kg', 'medjool-dates-1kg', 'Large, juicy and honey-like.', 'Jumbo medjool dates with a chewy centre and a toffee sweetness. The one to reach for when you want a sweet bite without sugar.', 'dates', 'desert-gold', 'AB-1009', '1 kg', 48, 60, 52, 380, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Medjool_dates_as_luxury_item.jpg/960px-Medjool_dates_as_luxury_item.jpg', '100% natural medjool dates', 'featured', 'dates,jumbo'),
('Safwi Dates 500 g', 'safwi-dates-500g', 'Everyday dates, great value.', 'Semi-dry safwi dates with a firm bite and mild sweetness, the everyday dates for suhoor, baking and date syrup.', 'dates', 'oasis-farms', 'AB-1010', '500 g', 24, 30, 80, 205, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Pile_of_Dried_Dates_at_Barkin_Dogo_Market%2C_Kaduna_North_02.jpg/960px-Pile_of_Dried_Dates_at_Barkin_Dogo_Market%2C_Kaduna_North_02.jpg', '100% natural safwi dates', '', 'dates,everyday'),
('Date Syrup 500 ml', 'date-syrup-500ml', 'Naturally sweet, no added sugar.', 'Slow-cooked dates pressed into a thick, molasses-like syrup. A spoonful over yoghurt, pancakes or oatmeal.', 'dates', 'oasis-farms', 'AB-1011', '500 ml', 22, 27, 64, 140, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/Maple_syrup_bottle_Citadell%C3%A9_20190404_080933.jpg/960px-Maple_syrup_bottle_Citadell%C3%A9_20190404_080933.jpg', 'Dates, water', '', 'syrup,sweetener,natural'),
('Turmeric Powder 200 g', 'turmeric-powder-200g', 'High curcumin, deeply coloured.', 'Single-origin turmeric roots sun-dried and ground fine, with a bright colour that stains a curry in one pinch.', 'spices', 'herbaline', 'AB-1012', '200 g', 14, 18, 120, 420, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Chlorofeel_Spices_Turmeric%2C_Coriander_and_Cumin_Powder.jpg/960px-Chlorofeel_Spices_Turmeric%2C_Coriander_and_Cumin_Powder.jpg', '100% turmeric root', '', 'spice,ground,curry'),
('Red Chilli Powder 250 g', 'red-chilli-powder-250g', 'Hot, coarse-ground blend.', 'A blend of dried red chillies ground coarse so the heat opens slowly. Bright red, with no colour added.', 'spices', 'herbaline', 'AB-1013', '250 g', 16, 21, 96, 350, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Cayenne_and_other_chilli_powders.JPG/960px-Cayenne_and_other_chilli_powders.JPG', 'Dried red chillies, salt', 'flash', 'spice,hot,ground'),
('Cumin Seeds 200 g', 'cumin-seeds-200g', 'Whole, aromatic, oil-rich.', 'Plump whole cumin seeds that bloom instantly in hot oil. Earthy with a citrus edge, the base of most tempering.', 'spices', 'herbaline', 'AB-1014', '200 g', 12, 15, 140, 300, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Whole_Cumin_Seeds.jpg/960px-Whole_Cumin_Seeds.jpg', '100% whole cumin seeds', '', 'spice,whole,tempering'),
('Garam Masala 100 g', 'garam-masala-100g', 'House-ground, small batches.', 'Eleven whole spices dry-roasted and ground to order, so the aroma is still sharp when you open the tin.', 'spices', 'dildar', 'AB-1015', '100 g', 19, 24, 88, 260, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Garam_Masala_1.jpg/960px-Garam_Masala_1.jpg', 'Coriander, cumin, black pepper, cinnamon, cardamom, cloves, bay leaf, mace, nutmeg, star anise, fennel', 'featured', 'spice,blend,masala'),
('Whole Black Pepper 100 g', 'black-pepper-whole-100g', 'Malabar peppercorns.', 'Bold, wrinkled peppercorns with a sharp bite and a pine-like smell. Grind them over anything at the table.', 'spices', 'noor-pantry', 'AB-1016', '100 g', 15, 19, 110, 210, 'https://upload.wikimedia.org/wikipedia/commons/c/cb/RECALLED_%E2%80%93_Organic_Black_Peppercorns_%2813694484414%29.jpg', '100% black peppercorns', '', 'spice,whole,pepper'),
('Coriander Powder 200 g', 'coriander-powder-200g', 'Fresh-milled, lemony thickener.', 'Roasted coriander seeds milled fine, the mild and slightly sweet base that gives gravies body without heat.', 'spices', 'herbaline', 'AB-1017', '200 g', 11, 14, 130, 240, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Chlorofeel_Spices_Turmeric%2C_Coriander_and_Cumin_Powder_Packet.jpg/960px-Chlorofeel_Spices_Turmeric%2C_Coriander_and_Cumin_Powder_Packet.jpg', '100% coriander seeds', '', 'spice,ground'),
('Saffron Threads 1 g', 'saffron-threads-1g', 'Hand-picked crimson threads.', 'Pure saffron threads that bleed colour into warm milk in minutes. A pinch is enough for a whole pot of rice.', 'spices', 'qamar', 'AB-1018', '1 g', 46, 58, 26, 90, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Saffron_Red_Thread_%28_World%27s_Most_Expensive_Speices%29.jpg/960px-Saffron_Red_Thread_%28_World%27s_Most_Expensive_Speices%29.jpg', '100% saffron threads', 'featured,flash', 'spice,premium,gift'),
('Roasted Almonds 500 g', 'roasted-almonds-500g', 'Dry roasted, salt-free.', 'California almonds dry-roasted in small batches until crisp, with no oil and no salt added.', 'nuts-and-seeds', 'oasis-farms', 'AB-1019', '500 g', 47, 57, 66, 330, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Almond_in_an_open_shell.jpg/960px-Almond_in_an_open_shell.jpg', 'Almonds', 'featured', 'nuts,snack,protein'),
('Cashew Nuts W240 500 g', 'cashews-w240-500g', 'Whole W240, creamy and clean.', 'Grade W240 whole cashews, pale and unbroken, with the clean creamy bite you want in a sweet or a curry.', 'nuts-and-seeds', 'oasis-farms', 'AB-1020', '500 g', 58, 70, 44, 250, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/DFC_6137_Close-up_of_fresh_cashew_apples_yellow_fruits_and_shelled_cashew_kernels_at_a_local_market_in_Klet_Kaeo_Sattahip_Chon_Buri_Thailand.jpg/960px-DFC_6137_Close-up_of_fresh_cashew_apples_yellow_fruits_and_shelled_cashew_kernels_at_a_local_market_in_Klet_Kaeo_Sattahip_Chon_Buri_Thailand.jpg', 'Cashew nuts', 'flash', 'nuts,premium'),
('Pistachios 250 g', 'pistachios-250g', 'Split shells, deep green kernels.', 'Naturally splitting shells with plump green kernels inside, lightly salted and perfect for slow evenings.', 'nuts-and-seeds', 'qamar', 'AB-1021', '250 g', 42, 52, 38, 160, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Kernel_Pistachio.JPG/960px-Kernel_Pistachio.JPG', 'Pistachios, salt', 'featured', 'nuts,snack'),
('Walnut Halves 250 g', 'walnut-halves-250g', 'Light halves, no bitter skin.', 'Pale walnut halves with the bitter skin left on for the good fats. Crunchy in granola, rich in baked goods.', 'nuts-and-seeds', 'oasis-farms', 'AB-1022', '250 g', 39, 47, 40, 140, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/4_walnut_kernels.jpg/960px-4_walnut_kernels.jpg', 'Walnuts', '', 'nuts,healthy'),
('Chia Seeds 250 g', 'chia-seeds-250g', 'Black and white, gel-fast.', 'Cleaned chia seeds that swell into a gel in ten minutes, the easiest way to make a pudding or thicken a smoothie.', 'nuts-and-seeds', 'green-valley', 'AB-1023', '250 g', 21, 26, 72, 220, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Mexican_chia_seeds_%283%29.jpg/960px-Mexican_chia_seeds_%283%29.jpg', '100% chia seeds', 'organic', 'seeds,organic,healthy'),
('Pumpkin Seeds 250 g', 'pumpkin-seeds-250g', 'Raw kernels, green and flat.', 'Raw pumpkin kernels, unsalted, with a soft crunch. Over salads, in bread, or straight from the jar.', 'nuts-and-seeds', 'green-valley', 'AB-1024', '250 g', 24, 29, 58, 150, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Pumpkin_seed._img_029.jpg/960px-Pumpkin_seed._img_029.jpg', '100% pumpkin seeds', '', 'seeds,raw'),
('Basmati Rice 5 kg', 'basmati-rice-5kg', 'Aged long grain, fluffy.', 'Aged basmati with a nutty smell and grains that stretch long and stay separate once cooked. For biryani and plain rice alike.', 'rice', 'noor-pantry', 'AB-1025', '5 kg', 68, 82, 34, 300, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Raw_Basmati_Rice.jpg/960px-Raw_Basmati_Rice.jpg', '100% basmati rice', 'featured,flash', 'rice,aged,biryani'),
('Brown Rice 2 kg', 'brown-rice-2kg', 'Whole grain, fibre-rich.', 'Short brown rice with the bran left on, so it takes longer to cook and tastes nuttier. A good everyday swap.', 'rice', 'green-valley', 'AB-1026', '2 kg', 32, 39, 46, 130, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Tricolor_brown_rice.jpg/960px-Tricolor_brown_rice.jpg', '100% brown rice', 'organic', 'rice,wholegrain,organic'),
('Sella Rice 5 kg', 'sella-rice-5kg', 'Parboiled, holds its shape.', 'Parboiled rice that stays firm through a long simmer, the safe choice for party pulao and mixed rice.', 'rice', 'noor-pantry', 'AB-1027', '5 kg', 54, 65, 28, 180, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Cooked_basmati_rice_in_a_pot%2C_absorption_method%2C_fluffed.jpg/960px-Cooked_basmati_rice_in_a_pot%2C_absorption_method%2C_fluffed.jpg', '100% parboiled rice', '', 'rice,parboiled'),
('Whole Wheat Flour 5 kg', 'whole-wheat-flour-5kg', 'Stone ground, chakki fresh.', 'Whole wheat stone-ground with the germ left in, so the dough is soft and smells faintly sweet. For roti, paratha and bread.', 'flour-and-lentils', 'noor-pantry', 'AB-1028', '5 kg', 29, 35, 40, 260, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Brown_wheat_flour.jpg/960px-Brown_wheat_flour.jpg', '100% whole wheat', '', 'flour,wholegrain'),
