insert into public.product_images (product_id, url, alt, sort_order)
select id, image_url, name || ' photo', 0 from public.products;

insert into public.product_images (product_id, url, alt, sort_order)
select p.id, c.image_url, p.name || ' in context', 1
from public.products p
join public.categories c on c.id = p.category_id
where p.is_flash_sale = true and c.image_url is not null and c.image_url <> p.image_url;

