insert into public.reviews (product_id, author_name, rating, title, body, is_approved, created_at)
select p.id,
  (array['Amina S.', 'Yusuf A.', 'Fatima R.', 'Bilal K.', 'Noor H.', 'Omar D.', 'Sara M.', 'Khalid J.', 'Layla T.', 'Hassan B.', 'Mariam Q.', 'Tariq N.'])
    [1 + abs(hashtext(p.slug || t.title)) % 12],
  t.rating, t.title, t.body, true,
  now() - ((abs(hashtext(p.slug)) % 30) * interval '1 day') - (t.ord * interval '4 days')
from public.products p
cross join (values
  (5::int, 'Arrived fast and well packed', 'Ordered in the evening and it was at my door before lunch. Sealed properly and exactly as described.', 0::int),
  (5::int, 'The quality is genuine', 'I have bought this from three other shops and this one is clearly the better grade. I will keep reordering.', 1::int),
  (4::int, 'Good value for money', 'The price is fair for what you get. Packaging could be sturdier, but the product itself is fine.', 2::int),
  (5::int, 'Now a family favourite', 'We go through this every week. My kids ask for it by name, which says everything.', 3::int),
  (4::int, 'Does exactly what it says', 'Nothing surprising, in the best way. It is fresh, the label matches the jar and the total was right.', 4::int),
  (5::int, 'Would recommend to a neighbour', 'I messaged them on WhatsApp about a delivery time and they moved it for me. That is why I come back.', 5::int),
  (4::int, 'Fresh and tidy packing', 'The best before date was far away and the seal was intact. I ordered two this time.', 6::int),
  (5::int, 'Better than the shop near me', 'Same item, half the price, and it reached me before I expected it. No complaints at all.', 7::int),
  (4::int, 'Fine, will buy again', 'It is what the photo showed. I wish there was a bigger size, but the one I got is good.', 8::int),
  (5::int, 'Perfect for the week''s cooking', 'I planned three meals around this and it held up well. The taste was clean and consistent.', 9::int),
  (3::int, 'Okay, not amazing', 'It is usable and the delivery was on time, but I have had better at a similar price.', 10::int),
  (5::int, 'Great for gifting', 'Bought two as a gift for my mother and she asked where I got them. The jar looks premium.', 11::int),
  (4::int, 'Reliable everyday staple', 'This is the fourth time I have ordered it. Same taste, same packing, no surprises.', 12::int),
  (5::int, 'Excellent, no notes', 'From search to payment to the door it took ten minutes of my time. The item was perfect.', 13::int)
) t(rating, title, body, ord)
where abs(hashtext(p.slug || t.title)) % 5 in (0, 1, 2);

update public.products p
set rating_avg = agg.avg_rating, rating_count = agg.cnt
from (
  select product_id, round(avg(rating)::numeric, 2) as avg_rating, count(*) as cnt
  from public.reviews where is_approved = true group by product_id
) agg
where agg.product_id = p.id;